import os, re
root = "/bench/repo"
pattern = re.compile(r'(?<![a-zA-Z_])store\.Memo(?![a-zA-Z_])|(?<![a-zA-Z_])\*Memo(?![a-zA-Z_])|\[\]\*Memo(?![a-zA-Z_])|&Memo\{')
# For store package files, also match unqualified Memo in type positions
store_pattern = re.compile(r'func \(s \*Store\) (Create|List|Get)Memo|CreateMemo\(ctx context\.Context, create \*Memo\)|ListMemos\(ctx context\.Context, find \*FindMemo\) \(\[\]\*Memo')

files = set()
for dirpath, _, filenames in os.walk(root):
    if 'proto/gen' in dirpath:
        continue
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        path = os.path.join(dirpath, fn)
        try:
            text = open(path).read()
        except:
            continue
        if pattern.search(text):
            files.add(path)
        elif '/store/' in path and store_pattern.search(text):
            files.add(path)

for p in sorted(files):
    print(p.replace(root + '/', ''))
PY

